"""Private inputs + code-only graph budget comparison suite for Colab."""
import base64
import hashlib
import importlib.metadata
import importlib.util
import io
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import zipfile

CODE_PAYLOAD = ""
CODE_SHA = "d8b34617494f9b985c89d8e1f76f62fa3d14eb05dc29a205489d3c76db0642eb"
INPUT_ZIP_SHA = "c0ed20d554a83ed135ec604fe776dbe7a83e9639ac93299a4893ed7301b5b7f6"
INPUT_ZIP_NAME = "MUSTER_GRAPH_SUITE_PRIVATE_INPUTS_v1.zip"
WHEEL_SHA = "baf7f5a76bf980a8615f25e07763c7a5fe34b5dae2a1eaf7bc1f3dd3e27fcc7f"
MYDRIVE = Path("/content/drive/MyDrive")


def sha(path):
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        for data in iter(lambda: f.read(1 << 20), b""):
            h.update(data)
    return h.hexdigest()


def load(path, name):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return module


def safe_path(root, name):
    p = (root / name).resolve()
    if Path(name).is_absolute() or ".." in Path(name).parts or not p.is_relative_to(root.resolve()):
        raise RuntimeError("unsafe packaged path")
    return p


def unpack_code():
    blob = base64.b64decode(CODE_PAYLOAD, validate=True)
    if hashlib.sha256(blob).hexdigest() != CODE_SHA:
        raise RuntimeError("embedded code ZIP hash differs")
    root = Path("/content/muster_graph_suite_code") / CODE_SHA[:16]
    with zipfile.ZipFile(io.BytesIO(blob)) as z:
        manifest = json.loads(z.read("CODE_MANIFEST.json"))
        if set(z.namelist()) != set(manifest["files"]) | {"CODE_MANIFEST.json"}:
            raise RuntimeError("code inventory differs")
        for name, digest in manifest["files"].items():
            value = z.read(name)
            if hashlib.sha256(value).hexdigest() != digest:
                raise RuntimeError("embedded code member differs: " + name)
            target = safe_path(root, name)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(value)
        (root / "CODE_MANIFEST.json").write_bytes(z.read("CODE_MANIFEST.json"))
    return root, manifest


def obtain_inputs(campaign):
    campaign.ensure_persistent(MYDRIVE / "MUSTER_graph_budget_suite_20261116")
    local_zip = Path("/content") / INPUT_ZIP_NAME
    saved = MYDRIVE / "MUSTER_graph_budget_suite_20261116/assets" / INPUT_ZIP_NAME
    if not local_zip.is_file() or sha(local_zip) != INPUT_ZIP_SHA:
        if saved.is_file() and sha(saved) == INPUT_ZIP_SHA:
            shutil.copyfile(saved, local_zip)
        else:
            from google.colab import files
            print("비공개 입력 ZIP 하나를 선택하십시오:", INPUT_ZIP_NAME, flush=True)
            old_cwd = Path.cwd()
            try:
                os.chdir("/content")
                uploaded = files.upload()
            finally:
                os.chdir(old_cwd)
            if INPUT_ZIP_NAME not in uploaded:
                raise RuntimeError("required private input ZIP was not uploaded")
            del uploaded
    if sha(local_zip) != INPUT_ZIP_SHA:
        raise RuntimeError("private input ZIP hash mismatch; no model has been loaded")
    campaign.ensure_persistent(saved)
    saved.parent.mkdir(parents=True, exist_ok=True)
    if not saved.is_file() or sha(saved) != INPUT_ZIP_SHA:
        temp = saved.with_name(saved.name + ".copying")
        shutil.copyfile(local_zip, temp)
        if sha(temp) != INPUT_ZIP_SHA:
            raise RuntimeError("private Drive ZIP copy differs")
        os.replace(temp, saved)
    root = Path("/content/muster_graph_suite_inputs") / INPUT_ZIP_SHA[:16]
    with zipfile.ZipFile(local_zip) as z:
        manifest = json.loads(z.read("SUITE_ASSET_MANIFEST.json"))
        if set(z.namelist()) != set(manifest["files"]) | {"SUITE_ASSET_MANIFEST.json"}:
            raise RuntimeError("private input inventory differs")
        for name, entry in manifest["files"].items():
            target = safe_path(root, name)
            if target.is_file() and sha(target) == entry["sha256"]:
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            temp = target.with_name(target.name + ".copying")
            with z.open(name) as src, temp.open("wb") as dst:
                shutil.copyfileobj(src, dst)
            if sha(temp) != entry["sha256"]:
                raise RuntimeError("private input member differs: " + name)
            os.replace(temp, target)
    print("비공개 입력과 원 벡터7개 검증 완료. 재임베딩하지 않습니다.", flush=True)
    return root


def environment(code, inputs, cache, output):
    print("GPU·원 패키지·고정 모델 캐시를 준비합니다.", flush=True)
    gpu = subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total", "--format=csv,noheader,nounits"],
                         check=True, capture_output=True, text=True)
    name, size = gpu.stdout.strip().splitlines()[0].rsplit(",", 1)
    if "RTXPRO6000" not in name.upper().replace(" ", "") or int(size) < 90000:
        raise RuntimeError("the frozen comparison profile requires RTX PRO 6000 >=90000 MiB")
    before = importlib.metadata.version("torch")
    pins = {"sentence-transformers": "5.3.0", "transformers": "5.5.0", "rank-bm25": "0.2.2",
            "nltk": "3.10.0", "tiktoken": "0.14.0"}
    install = []
    for key, expected in pins.items():
        try:
            actual = importlib.metadata.version(key)
        except importlib.metadata.PackageNotFoundError:
            actual = None
        if actual != expected:
            install.append(key + "==" + expected)
    if install:
        subprocess.run([sys.executable, "-m", "pip", "install", "--quiet", *install], check=True)
    wheel = code / "wheel/muster_memory-1.0.0-py3-none-any.whl"
    if sha(wheel) != WHEEL_SHA:
        raise RuntimeError("frozen SDK wheel differs")
    subprocess.run([sys.executable, "-m", "pip", "install", "--quiet", "--no-deps", "--force-reinstall", str(wheel)], check=True)
    if importlib.metadata.version("torch") != before:
        raise RuntimeError("Colab torch changed")
    shared = Path("/content/muster_assembly_parallel_assets")
    os.environ.update(PYTHONHASHSEED="0", NLTK_DATA=str(shared / "nltk_data"),
                      TIKTOKEN_CACHE_DIR=str(shared / "tiktoken_cache"))
    import nltk
    data = Path(os.environ["NLTK_DATA"])
    data.mkdir(parents=True, exist_ok=True)
    if str(data) not in nltk.data.path:
        nltk.data.path.insert(0, str(data))
    try:
        nltk.data.find("tokenizers/punkt_tab")
    except LookupError:
        if not nltk.download("punkt_tab", download_dir=str(data), quiet=True):
            raise RuntimeError("NLTK assets not available")
    import tiktoken
    tiktoken.get_encoding("cl100k_base")
    tiktoken.get_encoding("o200k_base")
    model_manifest = inputs / "beam/MODEL_FILES.json"
    cache.mkdir(parents=True, exist_ok=True)
    command = [sys.executable, "-I", "-B", str(code / "helpers/prepare_pinned_model_cache.py"),
        "--manifest", str(model_manifest), "--manifest-sha256", sha(model_manifest), "--cache", str(cache),
        "--receipt", str(output / "MODEL_FILES_READBACK.json")]
    result = subprocess.run(command, check=True, capture_output=True, text=True,
                            env=dict(os.environ, HF_HUB_OFFLINE="0", TRANSFORMERS_OFFLINE="0"))
    if result.stdout:
        print(result.stdout, flush=True)
    print("원 SDK·모델·FP32·batch32/16·max2048 준비 완료. 답/judge API 0", flush=True)


def run():
    if sys.platform != "linux" or not Path("/content").is_dir():
        raise RuntimeError("real execution is Colab-only")
    code, manifest = unpack_code()
    campaign = load(code / "campaign.py", "_graph_suite_campaign")
    inputs = obtain_inputs(campaign)
    output = MYDRIVE / "MUSTER_graph_budget_suite_20261116/results" / CODE_SHA[:16]
    campaign.ensure_persistent(output)
    output.mkdir(parents=True, exist_ok=True)
    cache = Path("/content/muster_assembly_parallel_assets/hf")
    environment(code, inputs, cache, output)
    phase_configs = {
        "assembly": {"input_dir": str(inputs / "assembly"), "output_dir": "{output}/assembly", "mode": "run",
            "vectors_by_source": {s: str(inputs / "vectors" / (s + ".npy")) for s in ("D1", "D3", "GM1", "GM2", "GM3", "GM4", "M2A")},
            "batch_controls_dir": str(inputs / "batch_controls"),
            "wheel": str(code / "wheel/muster_memory-1.0.0-py3-none-any.whl"),
            "models_cache": "{cache}", "local_files_only": True},
        "beam": {"package_dir": str(inputs / "beam"), "output_dir": "{output}/beam", "mode": "run",
                 "models_cache": "{cache}", "local_files_only": True},
        "store26": {"package_dir": str(inputs / "store26"), "output_dir": "{output}/store26", "mode": "run",
                    "models_cache": "{cache}", "local_files_only": True},
    }
    config = {"schema": campaign.SCHEMA, "asset_dir": str(code), "output_dir": str(output),
        "local_dir": str(Path("/content/muster_graph_suite_work") / CODE_SHA[:16]), "models_cache": str(cache),
        "phases": [{"id": "comparison_suite", "module": "suite/orchestrator.py",
            "module_sha256": manifest["files"]["suite/orchestrator.py"],
            "config": {"asset_dir": str(code), "output_dir": "{output}", "models_cache": "{cache}",
                       "phase_configs": phase_configs, "max_workers": 2}}]}
    print("실행: KnowMe·GroupMem·Mem2Act 보충 → BEAM·MemConflict·Memora 병렬200/400", flush=True)
    print("LME-v2·RHELM·CloneMem 실행은 이 묶음에 없으며 새 결과:", output, flush=True)
    return campaign.run_campaign(config)


if __name__ == "__main__":
    raise SystemExit(0 if run()["status"] == "DONE" else 2)
